Here is an implementation of a queue data structure using two stacks in Python:

```python
class Stack:
    def __init__(self):
        self.items = []

    def is_empty(self):
        return not self.items

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if self.is_empty():
            raise IndexError("Stack is empty")
        return self.items.pop()

    def peek(self):
        if self.is_empty():
            raise IndexError("Stack is empty")
        return self.items[-1]

    def size(self):
        return len(self.items)


class Queue:
    def __init__(self):
        self.items = Stack()

    def is_empty(self):
        return self.items.is_empty()

    def enqueue(self, item):
        self.items.push(item)

    def dequeue(self):
        if self.items.is_empty():
            raise IndexError("Queue is empty")
        return self.items.pop()

    def front(self):
        if self.items.is_empty():
            raise IndexError("Queue is empty")
        return self.items.peek()

    def rear(self):
        if self.items.is_empty():
            raise IndexError("Queue is empty")
        return self.items.size() - 1

    def size(self):
        return self.items.size()
```

